//! md2a: convert MIT format signal files to AHA DB distribution tape
//! format (port of `convert/md2a.c`).
//!
//! The files generated by this program are in the format formerly used for
//! distribution of the AHA and MIT-BIH databases on half-inch 9-track
//! digital tape. It does *not* generate files in the format currently used
//! for distribution of the AHA database on floppy disk; `ad2m` can perform
//! the reverse conversion, however.
//
// This file is part of wfdb-x, an independent reimplementation of the WFDB
// Software Package in Python, C++, MATLAB/Octave, Rust, Julia, R and Kotlin.
//
// It is a Rust translation of convert/md2a.c from the WFDB Software Package
// 10.7.0, by George B. Moody. The translation follows the logic and behavior
// of the original program, but it is new code, not the original C code.
//
// Changes from the original: none, apart from the language and the --legacy
// option (as the first argument, it restores the original behavior).
//
// Original C program: convert/md2a.c, WFDB Software Package 10.7.0.
//   Copyright (C) 2001 George B. Moody.
// Rust translation and changes: Copyright (C) 2026 Reza Sameni.
//
// This program is free software: you can redistribute it and/or modify it
// under the terms of the GNU General Public License as published by the Free
// Software Foundation, either version 3 of the License, or (at your option)
// any later version. See LICENSE.

use wfdbx::cstd;
use wfdbx::{ceprintf, Siginfo, WFDB_MAXSIG};

const EODF: i32 = 0o100000; // AHA data file end-of-data marker

const HELP_STRINGS: &[&[u8]] = &[
    b"usage: %s -o AHAFILE -r RECORD [ OPTIONS ... ]\n",
    b"where AHAFILE is the name of the AHA-format output signal file,",
    b"RECORD is the record name, and OPTIONS may include:",
    b" -h         print this usage summary",
    b" -n NEWREC  create a header file for the output signal file, so it",
    b"             may be read as record NEWREC",
];

fn help(pname: &[u8]) {
    ceprintf!(HELP_STRINGS[0], pname);
    for s in &HELP_STRINGS[1..] {
        ceprintf!(b"%s\n", s);
    }
}

fn main() {
    let mut argv = cstd::args();
    wfdbx::wfdbx_legacy_args(&mut argv); // wfdb-x: --legacy (original behavior)
    let argc = argv.len();
    let pname = cstd::prog_name(&argv[0]).to_vec();
    let mut nrec: Option<&[u8]> = None;
    let mut ofname: Option<&[u8]> = None;
    let mut record: Option<&[u8]> = None;
    let mut s = vec![Siginfo::default(); WFDB_MAXSIG as usize];

    let mut i = 1;
    while i < argc {
        let a = &argv[i];
        if a.first() == Some(&b'-') {
            match a.get(1).copied().unwrap_or(0) {
                b'h' => {
                    // help requested
                    help(&pname);
                    cstd::exit(1);
                }
                b'n' => {
                    // new record name follows
                    i += 1;
                    if i >= argc {
                        ceprintf!(b"%s: new record name must follow -n\n", pname);
                        cstd::exit(1);
                    }
                    nrec = Some(&argv[i]);
                }
                b'o' => {
                    // output file name follows
                    i += 1;
                    if i >= argc {
                        ceprintf!(
                            b"%s: name of AHA-format output file must follow -o\n",
                            pname
                        );
                        cstd::exit(1);
                    }
                    ofname = Some(&argv[i]);
                }
                b'r' => {
                    i += 1;
                    if i >= argc {
                        ceprintf!(b"%s: record name must follow -r\n", pname);
                        cstd::exit(1);
                    }
                    record = Some(&argv[i]);
                }
                _ => {
                    ceprintf!(b"%s: unrecognized option %s\n", pname, a);
                    cstd::exit(1);
                }
            }
        } else {
            ceprintf!(b"%s: unrecognized argument %s\n", pname, a);
            cstd::exit(1);
        }
        i += 1;
    }
    let (Some(ofname), Some(record)) = (ofname, record) else {
        help(&pname);
        cstd::exit(1);
    };

    // Give up unless at least one input signal is readable.
    let nsig = wfdbx::isigopen(record, &mut s[..], WFDB_MAXSIG);
    if nsig < 1 {
        cstd::exit(2);
    }
    let n = nsig as usize;

    // Check that the new record name is legal before proceeding. Note that
    // this step creates a header file in the current directory which is
    // overwritten below, after the processing is completed.
    if let Some(nrec) = nrec {
        if wfdbx::newheader(nrec) < 0 {
            cstd::exit(3);
        }
    }

    // Set the output signal specifications.
    for si in s.iter_mut().take(n) {
        si.fname = Some(cstd::cstr(ofname).to_vec());
        si.desc = Some(Vec::new());
        si.group = 0;
        si.fmt = 16;
    }

    // Give up if the output cannot be written.
    if wfdbx::osigfopen(&s[..n], nsig as u32) < nsig {
        cstd::exit(4);
    }

    // Copy the input to the output. Reformatting is handled by putvec().
    // x has one element per output sample of a frame (at least
    // WFDB_MAXSIG); getvec sets the first nsig, the others stay zero. (In
    // C, x is an uninitialized array of WFDB_MAXSIG; see "Undefined
    // behaviors" in docs/KNOWN_C_BEHAVIORS.md.)
    let nout: usize = s.iter().take(n).map(|si| si.spf.max(1) as usize).sum();
    let mut x = vec![0i32; nout.max(WFDB_MAXSIG as usize)];
    while wfdbx::getvec(&mut x) == nsig && wfdbx::putvec(&x) == nsig {}

    // Write the new header file if requested.
    if let Some(nrec) = nrec {
        wfdbx::newheader(nrec);
    }

    // Write the end-of-data marker.
    for v in x.iter_mut().take(n) {
        *v = EODF;
    }
    wfdbx::putvec(&x);

    // Clean up.
    wfdbx::wfdbquit();
    cstd::exit(0);
}
